class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online_status = [True] * numberOfUsers
        offline_until = [-1] * numberOfUsers

        for event in events:
            event_type, timestamp_str, data = event
            timestamp = int(timestamp_str)

            # Update online status for all users whose offline period has ended
            for user_id in range(numberOfUsers):
                if not online_status[user_id] and offline_until[user_id] != -1 and timestamp >= offline_until[user_id]:
                    online_status[user_id] = True
                    offline_until[user_id] = -1

            if event_type == "OFFLINE":
                user_id = int(data)
                # User goes offline for 60 time units
                online_status[user_id] = False
                offline_until[user_id] = timestamp + 60
            elif event_type == "MESSAGE":
                if data == "ALL":
                    for user_id in range(numberOfUsers):
                        mentions[user_id] += 1
                elif data == "HERE":
                    for user_id in range(numberOfUsers):
                        if online_status[user_id]:
                            mentions[user_id] += 1
                else:
                    tokens = data.split()
                    for token in tokens:
                        if token.startswith("id"):
                            user_id = int(token[2:])
                            mentions[user_id] += 1

        return mentions

