class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        from collections import deque
        n = len(nums)
        minDeque, maxDeque = deque(), deque()
        result = 0
        for i in range(n):
            while minDeque and minDeque[0] < i - k + 1:
                minDeque.popleft()
            while maxDeque and maxDeque[0] < i - k + 1:
                maxDeque.popleft()
            while minDeque and nums[minDeque[-1]] > nums[i]:
                minDeque.pop()
            while maxDeque and nums[maxDeque[-1]] < nums[i]:
                maxDeque.pop()
            minDeque.append(i)
            maxDeque.append(i)
            result += nums[minDeque[0]] + nums[maxDeque[0]]
        return result

