class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        dp = {0: 1}
        for num in nums:
            new_dp = dp.copy()
            for alt_sum, product in dp.items():
                new_alt_sum = alt_sum + num
                new_product = product * num
                if new_product <= limit:
                    if new_alt_sum not in new_dp or new_product > new_dp[new_alt_sum]:
                        new_dp[new_alt_sum] = new_product
                new_alt_sum = alt_sum - num
                if new_product <= limit:
                    if new_alt_sum not in new_dp or new_product > new_dp[new_alt_sum]:
                        new_dp[new_alt_sum] = new_product
            dp = new_dp
        return dp.get(k, -1)

