    sys.setrecursionlimit(1 << 25)
    H, W = map(int, sys.stdin.readline().split())
    S = [sys.stdin.readline().strip() for _ in range(H)]

    # Find the minimal bounding rectangle of all known black cells.
    min_row, max_row = H, -1
    min_col, max_col = W, -1
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                if i < min_row:
                    min_row = i
                if i > max_row:
                    max_row = i
                if j < min_col:
                    min_col = j
                if j > max_col:
                    max_col = j

    # Check if we can fill the rectangle [min_row..max_row][min_col..max_col] with black.
    for i in range(min_row, max_row + 1):
        for j in range(min_col, max_col + 1):
            if S[i][j] == '.':
                print("No")
                return

    # Check if there are any black cells outside the rectangle.
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                if not (min_row <= i <= max_row and min_col <= j <= max_col):
                    print("No")
                    return

    print("Yes")

