def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    N, *rest = map(int, sys.stdin.read().split())
    P = rest
    class BIT:
        def __init__(self, n):
            self.n = n
            self.bit = [0] * (n + 1)
        def add(self, i, x):
            while i <= self.n:
                self.bit[i] += x
                i += i & -i
        def sum(self, i):
            s = 0
            while i > 0:
                s += self.bit[i]
                i -= i & -i
            return s
        def kth(self, k):
            i = 0
            bit_mask = 1 << (self.n.bit_length() - 1)
            while bit_mask > 0:
                t = i + bit_mask
                if t <= self.n and self.bit[t] < k:
                    i = t
                    k -= self.bit[t]
                bit_mask >>= 1
            return i + 1
    bit = BIT(N)
    for i in range(1, N + 1):
        bit.add(i, 1)
    ans = [0] * (N + 1)
    for i in range(N, 0, -1):
        k = P[i - 1]
        pos = bit.kth(k)
        ans[pos] = i
        bit.add(pos, -1)
    print(' '.join(map(str, ans[1:])))
