def solve():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))
    max_A = max(A)
    freq = [0] * (max_A + 1)
    for a in A:
        freq[a] += 1
    div_count = [0] * (max_A + 1)
    for d in range(1, max_A + 1):
        for multiple in range(d, max_A + 1, d):
            div_count[d] += freq[multiple]
    ans = [0] * N
    for idx, a in enumerate(A):
        best = 1
        limit = int(math.isqrt(a))
        for d in range(1, limit + 1):
            if a % d == 0:
                d1 = d
                d2 = a // d
                if div_count[d1] >= K:
                    best = max(best, d1)
                if div_count[d2] >= K:
                    best = max(best, d2)
        ans[idx] = best
    print('\n'.join(map(str, ans)))

