def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    N, M = map(int, sys.stdin.readline().split())
    parent = list(range(N))
    rank = [0] * N
    bip = [True] * N

    def find(x):
        if parent[x] != x:
            px = find(parent[x])
            parent[x] = px[0]
            bip[x] ^= px[1]
        return parent[x], bip[x]

    for _ in range(M):
        u, v = map(int, sys.stdin.readline().split())
        u -= 1
        v -= 1
        ru, bu = find(u)
        rv, bv = find(v)
        if ru == rv:
            if bu == bv:
                bip[ru] = False
        else:
            if rank[ru] < rank[rv]:
                ru, rv = rv, ru
                bu, bv = bv, bu
            parent[rv] = ru
            bip[rv] = bu ^ bv ^ 1
            bip[ru] = bip[ru] and bip[rv]
            if rank[ru] == rank[rv]:
                rank[ru] += 1

    seen = [False] * N
    cnt_even = cnt_odd = 0
    for i in range(N):
        ri, bi = find(i)
        if not seen[ri]:
            seen[ri] = True
            if bip[ri]:
                cnt_even += 1
            else:
                cnt_odd += 1

    if cnt_odd % 2 == 1:
        print("Aoki")
    else:
        print("Takashahi")

