    queries = [int(input()) for _ in range(Q)]
    max_A = max(queries)

    # Precompute 400 numbers up to max_A
    limit = int(math.isqrt(max_A)) + 1
    primes = []
    is_prime_sieve = [True] * (limit + 1)
    for num in range(2, limit + 1):
        if is_prime_sieve[num]:
            primes.append(num)
            for multiple in range(num * num, limit + 1, num):
                is_prime_sieve[multiple] = False

    # Generate 400 numbers
    max_check = int(math.isqrt(max_A)) + 1
    four_hundred_numbers = set()
    for i, p in enumerate(primes):
        p2 = p * p
        if p2 > max_A:
            break
        for q in primes[i+1:]:
            q2 = q * q
            if p2 * q2 > max_A:
                break
            four_hundred_numbers.add(p2 * q2)

    # Process queries
    for A in queries:
        if A in four_hundred_numbers:
